prakriya brihat_ank_tak(x, n, base, out) {
    vitti src = x
    vitti c = n
    vitti b = base
    vitti dst = out
    yadi (b < 2) { nivartanam 0 }
    yadi (b > 16) { nivartanam 0 }
    yadi (c < 1) {
        dst[0] = 0
        nivartanam 1
    }
    yadi (c > 288230376151711743) { nivartanam 0 - 1 }   # R39: c * 4 * 8 must not wrap
    vitti w = nirmmita(c * 8)
    yadi (w == 0 && c > 0) { nivartanam 0 - 1 }
    vitti i = 0
    yavat (i < c) {
        w[i] = src[i]
        i = i + 1
    }
    yadi (brihat_asti_shunyank(w, c) == 1) {
        dst[0] = 0
        nivartanam 1
    }
    # rev holds the digits LSB-first: base 2 needs ceil(n*log2(10))
    # = ceil(3.33*n) cells; 4*n is safe for every base.
    vitti rev = nirmmita(c * 4 * 8)
    yadi (rev == 0 && c > 0) { nivartanam 0 - 1 }
    vitti rlen = 0
    vitti cont = 1
    yavat (cont == 1) {
        yadi (brihat_asti_shunyank(w, c) == 1) {
            cont = 0
        } anya {
            vitti rem = 0
            vitti k = c - 1
            yavat (k >= 0) {
                vitti cur = rem * 10 + w[k]
                w[k] = cur / b
                rem = cur % b
                k = k - 1
            }
            rev[rlen] = rem
            rlen = rlen + 1
        }
    }
    vitti p = 0
    yavat (p < rlen) {
        dst[p] = rev[rlen - 1 - p]
        p = p + 1
    }
    nivartanam rlen
}

# brihat_ank_se(d, count, base, x, n) — parse `count` digit values
# from mala `d` (MSB first) in `base` into n-digit bigint x.
# Returns 1 on success, 0 if a digit >= base. Base outside 2..16
# returns 0 (the old code accepted any base, so base 0/1/negative
# silently mis-parsed).

prakriya brihat_ank_se(d, count, base, x, n) {
    vitti src = d
    vitti cnt = count
    vitti b = base
    vitti dst = x
    vitti c = n
    yadi (b < 2) { nivartanam 0 }
    yadi (b > 16) { nivartanam 0 }
    brihat_shunyank(dst, c)
    vitti p = 0
    yavat (p < cnt) {
        vitti dv = src[p]
        yadi (dv < 0) { nivartanam 0 }
        yadi (dv >= b) { nivartanam 0 }
        # dst = dst * b + dv
        vitti carry = dv
        vitti k = 0
        yavat (k < c) {
            vitti cur = dst[k] * b + carry
            dst[k] = cur % 10
            carry = cur / 10
            k = k + 1
        }
        p = p + 1
    }
    nivartanam 1
}

prakriya ank_gan(n) {
    vitti x = n
    vitti minv = (0 - 9223372036854775807) - 1
    # MIN: |MIN| has 19 digits, but 0 - MIN wraps to MIN.
    yadi (x == minv) { nivartanam 19 }
    yadi (x < 0) { x = 0 - x }
    vitti c = 1
    yavat (x >= 10) {
        x = x / 10
        c = c + 1
    }
    nivartanam c
}

# ank_yog(n) — sum of the decimal digits of n (sign ignored; MIN counts as 89).

prakriya ank_yog(n) {
    vitti x = n
    vitti minv = (0 - 9223372036854775807) - 1
    # MIN: digit sum of 9223372036854775808 is 89.
    yadi (x == minv) { nivartanam 89 }
    yadi (x < 0) { x = 0 - x }
    vitti s = 0
    yavat (x > 0) {
        s = s + (x % 10)
        x = x / 10
    }
    nivartanam s
}

# viparyay_ank(n) — n with its decimal digits reversed, sign kept (e.g. -123 -> -321).

prakriya viparyay_ank(n) {
    vitti x = n
    vitti r = 0
    vitti minv = (0 - 9223372036854775807) - 1
    # Negatives reverse with the util_chinha: viparyay_ank(-123) = -321.
    # MIN: reverse of 9223372036854775808, negated.
    yadi (x == minv) { nivartanam 0 - 8085774586302733229 }
    yadi (x < 0) { nivartanam 0 - viparyay_ank(0 - x) }
    yavat (x > 0) {
        r = r * 10 + (x % 10)
        x = x / 10
    }
    nivartanam r
}

# asti_vilom(n) — 1 if n reads the same backwards (a palindrome); negatives are never palindromes.

prakriya asti_vilom(n) {
    # Negatives are not palindromes (the '-' is not a digit).
    yadi (n < 0) { nivartanam 0 }
    vitti r = viparyay_ank(n)
    nivartanam r == n
}

# seemit(n, lo, hi) — n clamped into [lo, hi]: lo if n < lo, hi if n > hi, else n.

prakriya seemit(n, lo, hi) {
    vitti x = n
    vitti a = lo
    vitti b = hi
    yadi (x < a) { nivartanam a }
    yadi (x > b) { nivartanam b }
    nivartanam x
}

# fib(n) — the nth Fibonacci number (fib(0) = 0, fib(1) = 1), iterative; wraps past int64.

prakriya fib(n) {
    vitti x = n
    yadi (x < 2) { nivartanam x }
    vitti a = 0
    vitti b = 1
    vitti i = 2
    yavat (i <= x) {
        vitti t = a + b
        a = b
        b = t
        i = i + 1
    }
    nivartanam b
}

# asti_sampurna(n) — 1 if n is a perfect number (equals the sum of its proper divisors), else 0.

prakriya asti_sampurna(n) {
    vitti x = n
    yadi (x < 2) { nivartanam 0 }
    vitti s = 1
    vitti d = 2
    # Division bound, not d * d: d * d overflows for x near MAX
    # (the vargit wraps negative, the condition stays true, and
    # the loop never terminates).
    yavat (d <= x / d) {
        yadi (x % d == 0) {
            s = s + d
            yadi (d != x / d) { s = s + (x / d) }
        }
        d = d + 1
    }
    nivartanam s == x
}

# collatz_charan(n) — steps for the Collatz sequence from n to reach 1; -1 if n < 1 or 3x+1 would overflow.

prakriya collatz_charan(n) {
    vitti x = n
    vitti c = 0
    # No Collatz sequence starting at x < 1 reaches 1 (0 stays 0,
    # negatives cycle), so -1 means "does not reach 1". The same
    # sentinel covers the 3x+1 overflow: 3x+1 overflows int64 when
    # x > (MAX-1)/3 = 3074457345618258602, and the wrapped value
    # would cycle forever instead of reaching 1.
    yadi (x < 1) { nivartanam 0 - 1 }
    yavat (x != 1) {
        yadi (x % 2 == 0) { x = x / 2 } anya {
            yadi (x > 3074457345618258602) { nivartanam 0 - 1 }
            x = 3 * x + 1
        }
        c = c + 1
    }
    nivartanam c
}

prakriya anukram_maap_ashtak(n) {
    nivartanam 8 + n
}

# anukram_khip_i64(out, pos, cap, v) — write v as 8 LE bytes at
# out+pos. Returns pos + 8, or -1 if it would overrun cap.

prakriya anukram_khip_i64(out, pos, cap, v) {
    vitti dst = out
    vitti p = pos
    vitti c = cap
    vitti val = v
    yadi (p < 0) { nivartanam 0 - 1 }
    yadi (p > c - 8) { nivartanam 0 - 1 }   # R37: p + 8 could wrap
    vitti i = 0
    yavat (i < 8) {
        # Floor division: Sutram's / and % truncate toward zero,
        # which would give a negative byte for negative val. The
        # byte must be in [0, 255] for two's-complement LE.
        vitti q = val / 256
        yadi (val < 0) {
            yadi (val % 256 != 0) { q = q - 1 }
        }
        akshar_rakh(dst, p + i, val - q * 256)
        val = q
        i = i + 1
    }
    nivartanam p + 8
}

# anukram_grah_i64(buf, pos, cap, out) — read 8 LE bytes at buf+pos,
# write the value into out[0]. Returns pos + 8, or -1 on overrun.

prakriya anukram_khip_ashtak(out, pos, cap, src, n) {
    vitti dst = out
    vitti p = pos
    vitti c = cap
    vitti s = src
    vitti cnt = n
    yadi (cnt < 0) { nivartanam 0 - 1 }
    yadi (p < 0) { nivartanam 0 - 1 }
    yadi (p > c - 8) { nivartanam 0 - 1 }   # R37: subtract; never add, the sum wraps
    yadi (cnt > c - 8 - p) { nivartanam 0 - 1 }
    vitti p2 = anukram_khip_i64(dst, p, c, cnt)
    vitti i = 0
    yavat (i < cnt) {
        akshar_rakh(dst, p2 + i, akshar(s, i))
        i = i + 1
    }
    nivartanam p2 + cnt
}

# anukram_grah_ashtak(buf, pos, cap, dst, out_n) — read a
# length-prefixed payload: length into out_n[0], payload into dst.
# Returns the new cursor, or -1 on overrun / negative length.

prakriya anukram_grah_ashtak(buf, pos, cap, dst, out_n) {
    vitti src = buf
    vitti p = pos
    vitti c = cap
    vitti d = dst
    vitti on = out_n
    # out_n doubles as the length cell for the inner read.
    vitti p2 = anukram_grah_i64(src, p, c, on)
    yadi (p2 == 0 - 1) { nivartanam 0 - 1 }
    vitti cnt = on[0]
    yadi (cnt < 0) { nivartanam 0 - 1 }
    # R37: cnt is read from the buffer; p2 + cnt wrapped for a corrupt length
    yadi (cnt > c - p2) { nivartanam 0 - 1 }
    vitti i = 0
    yavat (i < cnt) {
        akshar_rakh(d, i, akshar(src, p2 + i))
        i = i + 1
    }
    on[0] = cnt
    nivartanam p2 + cnt
}

prakriya brihat_ank_se_laghu(val, arr, n) {
    vitti v = val
    vitti a = arr
    vitti c = n
    vitti i = 0
    vitti minv = (0 - 9223372036854775807) - 1
    vitti ismin = 0
    yadi (v == minv) {
        ismin = 1
        v = 9223372036854775807
    }
    yadi (v < 0) { v = 0 - v }
    yavat (i < c) {
        likh8(a + i * 8, v % 10)
        v = v / 10
        i = i + 1
    }
    yadi (v > 0) { nivartanam 0 }
    yadi (ismin == 1) {
        # add 1 to the digit array: |MIN| = MAX + 1
        vitti carry = 1
        vitti j = 0
        yavat (j < c) {
            yadi (carry == 1) {
                vitti d = pad8(a + j * 8) + 1
                yadi (d == 10) {
                    likh8(a + j * 8, 0)
                } anya {
                    likh8(a + j * 8, d)
                    carry = 0
                }
            }
            j = j + 1
        }
        yadi (carry == 1) { nivartanam 0 }
    }
    nivartanam 1
}

# brihat_ank_tak_laghu(arr, n) — convert digit array back to int (for verification)
# Only correct if the value fits in an int.

prakriya brihat_ank_tak_laghu(arr, n) {
    vitti a = arr
    vitti c = n
    vitti r = 0
    vitti i = c - 1
    yavat (i >= 0) {
        r = r * 10 + pad8(a + i * 8)
        i = i - 1
    }
    nivartanam r
}

# brihat_pratilip(dst, src, n) — copy n digits

prakriya brihat_pratilip(dst, src, n) {
    vitti d = dst
    vitti s = src
    vitti c = n
    vitti i = 0
    yavat (i < c) {
        likh8(d + i * 8, pad8(s + i * 8))
        i = i + 1
    }
    nivartanam 0
}

# brihat_tul(a, b, n) — compare: 1 if a > b, -1 if a < b, 0 if equal

prakriya brihat_tul(a, b, n) {
    vitti x = a
    vitti y = b
    vitti c = n
    vitti i = c - 1
    yavat (i >= 0) {
        vitti dx = pad8(x + i * 8)
        vitti dy = pad8(y + i * 8)
        yadi (dx > dy) { nivartanam 1 }
        yadi (dx < dy) { nivartanam -1 }
        i = i - 1
    }
    nivartanam 0
}

# brihat_yuj(a, b, res, n) — res = a + b; returns final carry (0 or 1)

prakriya brihat_nyun(a, b, res, n) {
    vitti x = a
    vitti y = b
    vitti r = res
    vitti c = n
    vitti borrow = 0
    vitti i = 0
    yavat (i < c) {
        vitti d = pad8(x + i * 8) - pad8(y + i * 8) - borrow
        yadi (d < 0) {
            likh8(r + i * 8, d + 10)
            borrow = 1
        } anya {
            likh8(r + i * 8, d)
            borrow = 0
        }
        i = i + 1
    }
    nivartanam borrow
}

# brihat_gun(a, b, res, n) — res = a * b; res must have 2n digits
# Returns 0 on success.

prakriya brihat_asti_shunyank(arr, n) {
    vitti a = arr
    vitti c = n
    vitti i = 0
    yavat (i < c) {
        yadi (pad8(a + i * 8) != 0) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# brihat_bhajshesh(a, b, q, r, n) — q = a / b, r = a % b (a,b,q,r are n-digit)
# Uses long division, one decimal digit at a time. Division by zero is
# defined, not a hang: q = 0, r = a (so q*b + r == a still holds).

prakriya brihat_bhajshesh(a, b, q, r, n) {
    vitti x = a
    vitti y = b
    vitti qq = q
    vitti rr = r
    vitti c = n
    # zero q and r
    vitti i = 0
    yavat (i < c) {
        likh8(qq + i * 8, 0)
        likh8(rr + i * 8, 0)
        i = i + 1
    }
    yadi (brihat_asti_shunyank(y, c) == 1) {
        # b == 0: q = 0 (already), r = a. Without this guard the
        # trial-subtraction loop below never terminates (rr >= 0
        # always, and subtracting 0 leaves rr unchanged).
        vitti m = 0
        yavat (m < c) {
            likh8(rr + m * 8, pad8(x + m * 8))
            m = m + 1
        }
        nivartanam 0
    }
    # long division from most significant digit
    i = c - 1
    yavat (i >= 0) {
        # r = r * 10 + a[i]: shift r left by one decimal digit
        vitti j = c - 1
        yavat (j > 0) {
            likh8(rr + j * 8, pad8(rr + (j - 1) * 8))
            j = j - 1
        }
        likh8(rr, pad8(x + i * 8))
        # q[i] = r / b (0-9), r = r % b — by trial subtraction
        vitti qd = 0
        yavat (brihat_tul(rr, y, c) >= 0) {
            # r = r - b (in place)
            vitti borrow = 0
            vitti k = 0
            yavat (k < c) {
                vitti d = pad8(rr + k * 8) - pad8(y + k * 8) - borrow
                yadi (d < 0) {
                    likh8(rr + k * 8, d + 10)
                    borrow = 1
                } anya {
                    likh8(rr + k * 8, d)
                    borrow = 0
                }
                k = k + 1
            }
            qd = qd + 1
        }
        likh8(qq + i * 8, qd)
        i = i - 1
    }
    nivartanam 0
}

# brihat_shesh(ank, shesh, res, n) — res = ank % shesh, where ank has 2n digits
# Helper for powmod. Uses long division. shesh == 0 is defined, not a
# hang: no reduction is applied, so res is the low n digits of num.
# Returns 0, or -1 (res unchanged) if its n-digit scratch cannot be allocated.

prakriya brihat_shesh(ank, shesh, res, n) {
    vitti c = n
    yadi (c < 1) { nivartanam 0 }
    yadi (c > 1152921504606846975) { nivartanam 0 - 1 }   # R39: c * 8 must not wrap
    vitti tr = 0
    yadi (brihat_asti_shunyank(shesh, c) == 0) {
        tr = nirmmita(c * 8)
        yadi (tr == 0) { nivartanam 0 - 1 }
    }
    nivartanam brihat_shesh_tr(ank, shesh, res, c, tr)
}

# brihat_shesh_tr(ank, shesh, res, n, scratch) — brihat_shesh with caller's n-digit scratch.

prakriya brihat_shesh_tr(ank, shesh, res, n, scratch) {
    vitti x = ank
    vitti m = shesh
    vitti r = res
    vitti c = n
    yadi (brihat_asti_shunyank(m, c) == 1) {
        vitti m2 = 0
        yavat (m2 < c) {
            likh8(r + m2 * 8, pad8(x + m2 * 8))
            m2 = m2 + 1
        }
        nivartanam 0
    }
    vitti tr = scratch
    brihat_shunyank(tr, c)
    vitti i = c * 2 - 1
    yavat (i >= 0) {
        # tr = tr * 10 + x[i]
        vitti j = c - 1
        yavat (j > 0) {
            likh8(tr + j * 8, pad8(tr + (j - 1) * 8))
            j = j - 1
        }
        likh8(tr, pad8(x + i * 8))
        # while tr >= m: tr -= m
        yavat (brihat_tul(tr, m, c) >= 0) {
            vitti bw = 0
            vitti k = 0
            yavat (k < c) {
                vitti d = pad8(tr + k * 8) - pad8(m + k * 8) - bw
                yadi (d < 0) {
                    likh8(tr + k * 8, d + 10)
                    bw = 1
                } anya {
                    likh8(tr + k * 8, d)
                    bw = 0
                }
                k = k + 1
            }
        }
        i = i - 1
    }
    brihat_pratilip(r, tr, c)
    nivartanam 0
}

# brihat_ghatmod(base, exp, shesh, res, n) — res = base^exp shesh shesh
# exp is a plain int and must be >= 0 (a negative exp returns 1:
# the loop never runs). shesh == 0 means "no reduction" (see
# brihat_shesh), so the result is base^exp truncated to n digits.
# res is n-digit. Returns 0, or -1 (res unchanged) if its scratch cannot be allocated.

prakriya brihat_ghatmod(base, exp, shesh, res, n) {
    vitti b = base
    vitti e = exp
    vitti m = shesh
    vitti r = res
    vitti c = n
    yadi (c < 1) { nivartanam 0 }
    yadi (c > 576460752303423487) { nivartanam 0 - 1 }   # R39: c * 2 * 8 must not wrap
    vitti t1 = nirmmita(c * 2 * 8)
    vitti bcur = nirmmita(c * 8)
    vitti tr = nirmmita(c * 8)
    yadi (c > 0 && (t1 == 0 || bcur == 0 || tr == 0)) { nivartanam 0 - 1 }
    brihat_ank_se_laghu(1, r, c)
    brihat_pratilip(bcur, b, c)
    yavat (e > 0) {
        yadi (e % 2 == 1) {
            brihat_gun(r, bcur, t1, c)
            brihat_shesh_tr(t1, m, r, c, tr)
        }
        brihat_gun(bcur, bcur, t1, c)
        brihat_shesh_tr(t1, m, bcur, c, tr)
        e = e / 2
    }
    nivartanam 0
}

prakriya dviguna(n) {
    vitti x = n
    vitti r = 1
    vitti i = 0
    yavat (i < x) {
        r = r * 2
        i = i + 1
    }
    nivartanam r
}

# meru(n, k) — the binomial coefficient C(n, k); 0 for k < 0 or k > n.

prakriya meru(n, k) {
    vitti top = n
    vitti r = k
    yadi (r < 0) { nivartanam 0 }
    yadi (r > top) { nivartanam 0 }
    yadi (r > top - r) { r = top - r }
    vitti res = 1
    vitti i = 1
    yavat (i <= r) {
        # R48: res * (top - r + i) / i is exact, but the product passed 2^63 for
        # answers that fit (meru(62, 31) came out negative, meru(100, 16) wrong).
        # Divide out g = mahattam(res, i) first: i / g then divides (top - r + i),
        # and no step is larger than C(top - r + i, i) <= the answer.
        vitti m = top - r + i
        vitti g = res
        vitti b = i
        yavat (b != 0) {
            vitti t = g % b
            g = b
            b = t
        }
        res = (res / g) * (m / (i / g))
        i = i + 1
    }
    nivartanam res
}

# matra_meru(n) — the nth Fibonacci number (matra_meru(0) = 0, matra_meru(1) = 1).

prakriya matra_meru(n) {
    vitti x = n
    yadi (x <= 0) { nivartanam 0 }
    yadi (x == 1) { nivartanam 1 }
    vitti a = 0
    vitti b = 1
    vitti i = 2
    yavat (i <= x) {
        vitti c = a + b
        a = b
        b = c
        i = i + 1
    }
    nivartanam b
}

# asti_guru(pat, i) — 1 if bit i of the integer pattern pat is set; 0 for i < 0 or i >= 64.

prakriya asti_guru(pat, i) {
    vitti p = pat
    vitti idx = i
    # Index must be a bit position: negative or >= 64 has no bit
    # (i >= 64 shifted the divisor to 0 and trapped with SIGFPE).
    yadi (idx < 0) { nivartanam 0 }
    yadi (idx >= 64) { nivartanam 0 }
    vitti d = 1
    vitti j = 0
    yavat (j < idx) {
        d = d * 2
        j = j + 1
    }
    nivartanam (p / d) % 2
}

# guru_gan(pat) — count of set bits in pat (population count); negatives return 0.

prakriya guru_gan(pat) {
    vitti p = pat
    vitti c = 0
    # Negative patterns return 0, as bit_gan (R28 contract).
    yavat (p > 0) {
        c = c + (p % 2)
        p = p / 2
    }
    nivartanam c
}

# meru_mala(a, n) — fills a[0..n] with the nth row of Pascal's triangle: a[i] = meru(n, i).

prakriya meru_mala(a, n) {
    vitti i = 0
    yavat (i <= n) {
        a[i] = meru(n, i)
        i = i + 1
    }
}

prakriya nirapeksh_mulya(n) {
    vitti x = n
    yadi (x < 0) {
        x = 0 - x
    }
    nivartanam x
}

# laghu2(a, b) — the smaller of a and b.

prakriya laghu2(a, b) {
    vitti x = a
    vitti y = b
    yadi (x < y) { nivartanam x }
    nivartanam y
}

# adhik2(a, b) — the larger of a and b.

prakriya adhik2(a, b) {
    vitti x = a
    vitti y = b
    yadi (x > y) { nivartanam x }
    nivartanam y
}

# mahattam(a, b) — greatest common divisor of a and b, always non-negative (mahattam(0, 0) = 0).

prakriya mahattam(a, b) {
    vitti x = a
    vitti y = b
    yavat (y != 0) {
        vitti t = y
        y = x % y
        x = t
    }
    # mahattam is non-negative by definition. The loop above can return a
    # negative value when the first argument is negative (e.g.
    # mahattam(-6, 4) was -2), so take the absolute value. mahattam(MIN, 0)
    # still returns MIN: |MIN| does not fit (wrapping, as nirapeksh_mulya).
    yadi (x < 0) { x = 0 - x }
    nivartanam x
}

# laghuttam(a, b) — least common multiple of a and b, always non-negative (laghuttam(0, 0) = 0).

prakriya laghuttam(a, b) {
    vitti g = mahattam(a, b)
    # mahattam(0, 0) is 0; without this guard (a / g) divides by zero and
    # the program traps (SIGFPE). laghuttam(0, 0) = 0 by convention.
    yadi (g == 0) { nivartanam 0 }
    # laghuttam is non-negative by definition (the product (a / g) * b can
    # be negative when exactly one input is). laghuttam(MIN, 2) still
    # returns MIN: the true value 2^63 does not fit (wrapping).
    vitti r = (a / g) * b
    yadi (r < 0) { r = 0 - r }
    nivartanam r
}

# ghat(base, e) — base raised to the power e (e >= 0; negative e returns 1, as the loop never runs).

prakriya ghat(base, e) {
    vitti b = base
    vitti n = e
    vitti r = 1
    yavat (n > 0) {
        r = r * b
        n = n - 1
    }
    nivartanam r
}

# kramgun(n) — n factorial (n!); 1 for n < 2; wraps past int64 for n >= 21.

prakriya kramgun(n) {
    # Iterative: the recursive form overflowed the call stack at
    # kramgun(100000) (SIGSEGV). Same values — multiplication
    # commutes shesh 2^64, so wrapping at n >= 21 is identical.
    vitti x = n
    vitti r = 1
    vitti i = 2
    yadi (x < 2) { nivartanam 1 }
    yavat (i <= x) {
        r = r * i
        i = i + 1
    }
    nivartanam r
}

# asti_abhajya(n) — 1 if n is prime, 0 otherwise (n < 2 is not prime).

prakriya asti_abhajya(n) {
    vitti x = n
    yadi (x < 2) { nivartanam 0 }
    vitti i = 2
    # Division bound, not i * i: i * i overflows for x near MAX
    # (the vargit wraps negative, the condition stays true, and
    # the loop never terminates for a large prime).
    yavat (i <= x / i) {
        yadi (x % i == 0) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# yog_tak(n) — sum 1 + 2 + ... + n, closed form n*(n+1)/2; 0 for n <= 0.

prakriya yog_tak(n) {
    # Closed form n*(n+1)/2 (the old loop took n iterations, so
    # yog_tak(4294967296) was ~4.3e9 iterations). Divide before
    # multiplying, by parity: even (n/2)*(n+1), odd n*(n/2+1).
    # The wrapping value equals the loop's (pinned: yog_tak(
    # 4294967296) == -9223372034707292160). n <= 0: 0, as the old loop.
    vitti x = n
    yadi (x <= 0) { nivartanam 0 }
    yadi (x % 2 == 0) { nivartanam (x / 2) * (x + 1) }
    nivartanam x * (x / 2 + 1)
}

# dvigun(n) — n doubled (n * 2).

prakriya ganit_seemit(v, lo, hi) {
    vitti x = v
    vitti a = lo
    vitti b = hi
    yadi (x < a) { nivartanam a }
    yadi (x > b) { nivartanam b }
    nivartanam x
}

prakriya kuttaka(a, b, c) {
    vitti old_r = a
    vitti r = b
    vitti old_s = 1
    vitti s = 0
    yavat (r != 0) {
        vitti q = old_r / r
        vitti tmp = old_r - q * r
        old_r = r
        r = tmp
        tmp = old_s - q * s
        old_s = s
        s = tmp
    }
    yadi (old_r == 0) { nivartanam 0 }
    vitti mult = c / old_r
    vitti res = old_s * mult
    vitti bb = b
    yadi (bb < 0) { bb = 0 - bb }
    yadi (bb > 0) {
        res = res % bb
        yadi (res < 0) { res = res + bb }
    }
    nivartanam res
}

# integer vargit root (floor)

prakriya ganita_vargmool(n) {
    vitti x = n
    yadi (x < 0) { nivartanam 0 }
    yadi (x < 2) { nivartanam x }
    # Binary search with a division bound. The old loop
    # `yavat ((i + 1) * (i + 1) <= x)` overflowed for x near MAX:
    # (i+1)^2 wraps negative, the condition stays true, and the
    # loop never terminates. mid <= x / mid is the same test
    # without ever squaring.
    vitti lo = 1
    vitti hi = x / 2 + 1
    vitti ans = 1
    yavat (lo <= hi) {
        vitti mid = lo + (hi - lo) / 2
        yadi (mid <= x / mid) {
            ans = mid
            lo = mid + 1
        } anya {
            hi = mid - 1
        }
    }
    nivartanam ans
}

# ganita_nirapeksh(n) — absolute value of n (the ganita-module spelling of nirapeksh_mulya).

prakriya ganita_nirapeksh(n) {
    vitti x = n
    yadi (x < 0) { nivartanam 0 - x }
    nivartanam x
}

# chakravala(out, n): solves x^2 - n*y^2 = 1 for least positive x, y.
# Writes out[0] = x and out[1] = y; caller must supply at least 2 writable qword cells.

prakriya ganita_janchit_yuj(a, b, ok) {
    vitti x = a
    vitti y = b
    vitti okp = ok
    vitti s = x + y
    yadi (x >= 0) {
        yadi (y >= 0) {
            yadi (s < 0) {
                okp[0] = 0
                nivartanam 0
            }
        }
    } anya {
        yadi (y < 0) {
            yadi (s >= 0) {
                okp[0] = 0
                nivartanam 0
            }
        }
    }
    okp[0] = 1
    nivartanam s
}

# ganita_janchit_nyun(a, b, ok) — a - b; ok[0] 1, or 0 on overflow
# (returns 0 then).

prakriya ganita_janchit_nyun(a, b, ok) {
    vitti x = a
    vitti y = b
    vitti okp = ok
    vitti d = x - y
    yadi (x >= 0) {
        yadi (y < 0) {
            yadi (d < 0) {
                okp[0] = 0
                nivartanam 0
            }
        }
    } anya {
        yadi (y >= 0) {
            yadi (d >= 0) {
                okp[0] = 0
                nivartanam 0
            }
        }
    }
    okp[0] = 1
    nivartanam d
}

# ganita_janchit_gun(a, b, ok) — a * b; ok[0] 1, or 0 on overflow
# (returns 0 then). The check is m / a == b, with the INT64_MIN * -1
# case handled explicitly (the division itself would SIGFPE there).

prakriya ganita_janchit_gun(a, b, ok) {
    vitti x = a
    vitti y = b
    vitti okp = ok
    vitti m = 0
    vitti minv = (0 - 9223372036854775807) - 1
    yadi (x == 0) {
        okp[0] = 1
        nivartanam 0
    }
    yadi (y == 0) {
        okp[0] = 1
        nivartanam 0
    }
    yadi (x == minv) {
        yadi (y == 0 - 1) {
            okp[0] = 0
            nivartanam 0
        }
    }
    yadi (y == minv) {
        yadi (x == 0 - 1) {
            okp[0] = 0
            nivartanam 0
        }
    }
    m = x * y
    yadi (m / x != y) {
        okp[0] = 0
        nivartanam 0
    }
    okp[0] = 1
    nivartanam m
}

# ganita_janchit_bhaj(a, b, ok) — truncating a / b; ok[0] 1, or 0 on
# division by zero or INT64_MIN / -1 (both would SIGFPE; returns 0).

prakriya ganita_janchit_bhaj(a, b, ok) {
    vitti x = a
    vitti y = b
    vitti okp = ok
    vitti minv = (0 - 9223372036854775807) - 1
    yadi (y == 0) {
        okp[0] = 0
        nivartanam 0
    }
    yadi (x == minv) {
        yadi (y == 0 - 1) {
            okp[0] = 0
            nivartanam 0
        }
    }
    okp[0] = 1
    nivartanam x / y
}

# ganita_janchit_shesh(a, b, ok) — truncating a % b (remainder takes the
# dividend's util_chinha); ok[0] 1, or 0 on b == 0 or INT64_MIN % -1.

prakriya ganita_janchit_shesh(a, b, ok) {
    vitti x = a
    vitti y = b
    vitti okp = ok
    vitti minv = (0 - 9223372036854775807) - 1
    yadi (y == 0) {
        okp[0] = 0
        nivartanam 0
    }
    yadi (x == minv) {
        yadi (y == 0 - 1) {
            okp[0] = 0
            nivartanam 0
        }
    }
    okp[0] = 1
    nivartanam x % y
}

# ganita_paripurna_yuj(a, b) — a + b, SATURATING: on overflow returns
# INT64_MAX (positive overflow) or INT64_MIN (negative overflow).

prakriya ganita_paripurna_yuj(a, b) {
    vitti x = a
    vitti y = b
    vitti maxv = 9223372036854775807
    vitti minv = (0 - 9223372036854775807) - 1
    vitti s = x + y
    yadi (x >= 0) {
        yadi (y >= 0) {
            yadi (s < 0) { nivartanam maxv }
        }
    } anya {
        yadi (y < 0) {
            yadi (s >= 0) { nivartanam minv }
        }
    }
    nivartanam s
}

# ganita_paripurna_nyun(a, b) — a - b, saturating (see ganita_paripurna_yuj).

prakriya ganita_paripurna_nyun(a, b) {
    vitti x = a
    vitti y = b
    vitti maxv = 9223372036854775807
    vitti minv = (0 - 9223372036854775807) - 1
    vitti d = x - y
    yadi (x >= 0) {
        yadi (y < 0) {
            yadi (d < 0) { nivartanam maxv }
        }
    } anya {
        yadi (y >= 0) {
            yadi (d >= 0) { nivartanam minv }
        }
    }
    nivartanam d
}

# ganita_paripurna_gun(a, b) — a * b, saturating (see ganita_paripurna_yuj).
# The overflow direction is the util_chinha of the true product.

prakriya ganita_paripurna_gun(a, b) {
    vitti x = a
    vitti y = b
    vitti maxv = 9223372036854775807
    vitti minv = (0 - 9223372036854775807) - 1
    vitti m = 0
    vitti neg = 0
    yadi (x == 0) { nivartanam 0 }
    yadi (y == 0) { nivartanam 0 }
    yadi (x == minv) {
        yadi (y == 0 - 1) { nivartanam maxv }
    }
    yadi (y == minv) {
        yadi (x == 0 - 1) { nivartanam maxv }
    }
    m = x * y
    yadi (m / x != y) {
        yadi (x < 0) { neg = 1 - neg }
        yadi (y < 0) { neg = 1 - neg }
        yadi (neg == 1) { nivartanam minv }
        nivartanam maxv
    }
    nivartanam m
}

# ganita_janchit_ghat(a, e, ok) — a^e for e >= 0 via repeated
# checked multiplication (WS3, R19); ok[0] 1, or 0 if e < 0 (no
# integer ghat) or the result overflows (returns 0 then). 0^0 = 1
# by the empty-product convention. O(e), but the loop exits early
# on overflow for every |a| >= 2 (a^e overflows by e = 63 at the
# latest); only the trivial bases -1, 0, 1 run the full loop.

prakriya ganita_janchit_ghat(a, e, ok) {
    vitti base = a
    vitti exp = e
    vitti okp = ok
    vitti r = 1
    vitti i = 0
    yadi (exp < 0) {
        okp[0] = 0
        nivartanam 0
    }
    yavat (i < exp) {
        r = ganita_janchit_gun(r, base, okp)
        yadi (okp[0] == 0) { nivartanam 0 }
        i = i + 1
    }
    okp[0] = 1
    nivartanam r
}

# ganita_janchit_kramgun(n, ok) — n! via repeated checked multiplication
# (WS3, R20); ok[0] 1, or 0 if n < 0 (no integer factorial) or the
# result overflows (returns 0 then). 0! = 1. 20! is the largest that
# fits (20! = 2432902008176640000); 21! overflows.

prakriya ganita_paripurna_ghat(a, e) {
    vitti base = a
    vitti exp = e
    vitti maxv = 9223372036854775807
    vitti minv = (0 - 9223372036854775807) - 1
    vitti r = 1
    vitti i = 0
    yadi (exp < 0) { nivartanam 0 }
    yavat (i < exp) {
        r = ganita_paripurna_gun(r, base)
        i = i + 1
        yadi (r == maxv) {
            yadi (base > 0) { nivartanam maxv }
            yadi ((exp - i) % 2 == 0) { nivartanam maxv }
            nivartanam minv
        }
        yadi (r == minv) {
            yadi (base > 0) { nivartanam minv }
            yadi ((exp - i) % 2 == 0) { nivartanam minv }
            nivartanam maxv
        }
    }
    nivartanam r
}

# ganita_paripurna_bhaj(a, b) — truncating a / b, saturating (WS4, R24): the
# sat_* companion of ganita_janchit_bhaj. INT64_MIN / -1 saturates to
# INT64_MAX (the true quotient 2^63 does not fit); b == 0 returns 0
# (the saturating form has no ok channel, so 0 is the documented
# sentinel — same as ganita_paripurna_ghat/ganita_paripurna_kramgun on invalid input). Guards both
# cases before dividing, so it never executes a trapping operation
# under a trapping compiler.

prakriya ganita_paripurna_bhaj(a, b) {
    vitti x = a
    vitti y = b
    vitti maxv = 9223372036854775807
    vitti minv = (0 - 9223372036854775807) - 1
    yadi (y == 0) { nivartanam 0 }
    yadi (x == minv) {
        yadi (y == 0 - 1) { nivartanam maxv }
    }
    nivartanam x / y
}

# ganita_paripurna_shesh(a, b) — truncating a % b (WS4, R24). Remainder never
# overflows mathematically (INT64_MIN % -1 is exactly 0), but the
# hardware operation still traps on MIN % -1 (same SIGFPE as MIN / -1),
# so this guards that case and returns 0 — which is also the exact
# result. b == 0 returns 0 (same sentinel as ganita_paripurna_bhaj). Guards before
# operating, so it never executes a trapping operation.

prakriya ganita_paripurna_shesh(a, b) {
    vitti x = a
    vitti y = b
    vitti minv = (0 - 9223372036854775807) - 1
    yadi (y == 0) { nivartanam 0 }
    yadi (x == minv) {
        yadi (y == 0 - 1) { nivartanam 0 }
    }
    nivartanam x % y
}

# ganita_janchit_nirapeksh(a, ok) — |a| (WS4, R24); ok[0] 1, or 0 on
# abs(INT64_MIN), which overflows (returns 0 then). The unary overflow
# the checked family did not cover: plain ganita_nirapeksh(MIN) silently
# wraps to MIN.

prakriya ganita_janchit_nirapeksh(a, ok) {
    vitti x = a
    vitti okp = ok
    vitti minv = (0 - 9223372036854775807) - 1
    yadi (x == minv) {
        okp[0] = 0
        nivartanam 0
    }
    okp[0] = 1
    yadi (x < 0) { nivartanam 0 - x }
    nivartanam x
}

# ganita_paripurna_nirapeksh(a) — |a|, saturating (WS4, R24):
# abs(INT64_MIN) saturates to INT64_MAX.

prakriya ganita_paripurna_kramgun(n) {
    vitti nn = n
    vitti maxv = 9223372036854775807
    vitti r = 1
    vitti i = 2
    yadi (nn < 0) { nivartanam 0 }
    yavat (i <= nn) {
        r = ganita_paripurna_gun(r, i)
        yadi (r == maxv) { nivartanam maxv }
        i = i + 1
    }
    nivartanam r
}

prakriya fnv1a_varna(s) {
    nivartanam fnv1a(s, vartani_aayam(s))
}

prakriya kalana_trapiz(kosh dasham xs, kosh dasham ys) {
    vitti n = kosh_len(xs)
    yadi (kosh_len(ys) < n) { n = kosh_len(ys) }
    yadi (n < 2) { nivartanam 0.0 }
    dasham total = 0.0
    vitti i = 0
    yavat (i < n - 1) {
        dasham h = xs[i + 1] - xs[i]
        total = total + h * (ys[i] + ys[i + 1]) / 2.0
        i = i + 1
    }
    nivartanam total
}

# Simpson's 1/3 rule over equally spaced samples. Needs an odd number of points
# (even intervals); for usable even n >= 4 drops the final sample; n < 3 uses kalana_trapiz.

prakriya simpson(kosh dasham xs, kosh dasham ys) {
    vitti n = kosh_len(xs)
    yadi (kosh_len(ys) < n) { n = kosh_len(ys) }
    yadi (n < 3) { nivartanam kalana_trapiz(xs, ys) }
    # if the count is even, drop the last point so the rule applies
    yadi ((n - 1) - ((n - 1) / 2) * 2 == 1) { n = n - 1 }
    dasham h = (xs[n - 1] - xs[0]) / (n - 1)
    dasham total = ys[0] + ys[n - 1]
    vitti i = 1
    yavat (i < n - 1) {
        yadi (i - (i / 2) * 2 == 1) {
            total = total + 4.0 * ys[i]
        } anya {
            total = total + 2.0 * ys[i]
        }
        i = i + 1
    }
    nivartanam total * h / 3.0
}

# ---------------------------------------------------------------
# Differentiation over sampled data
# ---------------------------------------------------------------

# Central difference at interior point i; one-sided at the ends.

prakriya pravan(kosh dasham xs, kosh dasham ys, i) {
    vitti n = kosh_len(xs)
    yadi (kosh_len(ys) < n) { n = kosh_len(ys) }
    yadi (n < 2) { nivartanam 0.0 }
    # Neighbouring pair: first, last, or centred. The two
    # sequential yadi (not yadi/anyatra) matter: for n == 2,
    # i == 0 satisfies the first but not the second, and the
    # centred branch would index xs[-1].
    vitti lo = i - 1
    vitti hi = i + 1
    yadi (i <= 0) { lo = 0; hi = 1 }
    yadi (i >= n - 1) { lo = n - 2; hi = n - 1 }
    # Zero spacing (duplicate x): no pravan is defined — return
    # 0.0 instead of inf / NaN (the old code divided by zero).
    dasham dx = xs[hi] - xs[lo]
    yadi (dx == 0.0) { nivartanam 0.0 }
    nivartanam (ys[hi] - ys[lo]) / dx
}

# Second derivative at an interior point (central, equally spaced assumption relaxed).

prakriya pravan2(kosh dasham xs, kosh dasham ys, i) {
    vitti n = kosh_len(xs)
    yadi (kosh_len(ys) < n) { n = kosh_len(ys) }
    yadi (i <= 0) { nivartanam 0.0 }
    yadi (i >= n - 1) { nivartanam 0.0 }
    dasham hl = xs[i] - xs[i - 1]
    dasham hr = xs[i + 1] - xs[i]
    # Zero spacing on either side (or hl == -hr, so the mean
    # spacing is 0): the second difference is undefined — 0.0.
    yadi (hl == 0.0) { nivartanam 0.0 }
    yadi (hr == 0.0) { nivartanam 0.0 }
    dasham dl = (ys[i] - ys[i - 1]) / hl
    dasham dr = (ys[i + 1] - ys[i]) / hr
    dasham hm = (hl + hr) / 2.0
    yadi (hm == 0.0) { nivartanam 0.0 }
    nivartanam (dr - dl) / hm
}

# ---------------------------------------------------------------
# Polynomials
# ---------------------------------------------------------------

# Horner evaluation: c[0] + c[1]x + c[2]x^2 + ...

prakriya bahu_ganana(kosh dasham c, dasham x) {
    vitti n = kosh_len(c)
    yadi (n == 0) { nivartanam 0.0 }
    dasham acc = c[n - 1]
    vitti k = n - 2
    yavat (k >= 0) {
        acc = acc * x + c[k]
        k = k - 1
    }
    nivartanam acc
}

# Bisection root of a polynomial on [lo, hi].
# CONTRACT: `ok` must already contain ONE element (call kosh_push(ok, 0.0) first).
# A kosh's capacity is not its length, so ok[0] is out of bounds until an element exists. Requires a util_chinha change across the interval,
# which is checked and reported by returning a NaN-like sentinel of 0.0 with ok=0.
# ok is returned through a one-element kosh so the caller can tell success from failure.

prakriya bahu_mula(kosh dasham c, dasham lo, dasham hi, kosh dasham ok) {
    dasham flo = bahu_ganana(c, lo)
    dasham fhi = bahu_ganana(c, hi)
    # need opposite signs; treat exact zeros first
    yadi (flo == 0.0) { ok[0] = 1.0; nivartanam lo }
    yadi (fhi == 0.0) { ok[0] = 1.0; nivartanam hi }
    yadi ((flo < 0.0) == (fhi < 0.0)) { ok[0] = 0.0; nivartanam 0.0 }
    dasham a = lo
    dasham b = hi
    vitti k = 0
    yavat (k < 80) {
        dasham m = (a + b) / 2.0
        dasham fm = bahu_ganana(c, m)
        yadi (fm == 0.0) { ok[0] = 1.0; nivartanam m }
        yadi ((fm < 0.0) == (flo < 0.0)) {
            a = m
            flo = fm
        } anya {
            b = m
        }
        k = k + 1
    }
    ok[0] = 1.0
    nivartanam (a + b) / 2.0
}

# ---------------------------------------------------------------
# A small helper: build a coefficient array from scratch is the caller's job
# (kosh_push on the caller's own kosh, which is allowed).
# ---------------------------------------------------------------

prakriya khand_mukt(bytes, n, out) {
    vitti s = bytes
    vitti cnt = n
    vitti dst = out
    vitti i = 0
    yadi (cnt <= 0) {
        dst[0] = 0
        nivartanam 0
    }
    yavat (i < cnt) {
        dst[i] = akshar(s, i)
        i = i + 1
    }
    dst[cnt] = 0
    nivartanam cnt
}

# khand_pratilip(src, n, out) — copy n bytes verbatim ("make me a real byte
# string from this"). Writes a 0 terminator at out[n]. Returns n.
# n <= 0 writes only the terminator, returns 0.

prakriya khand_pratilip(src, n, out) {
    vitti s = src
    vitti cnt = n
    vitti dst = out
    vitti i = 0
    yadi (cnt <= 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yavat (i < cnt) {
        akshar_rakh(dst, i, akshar(s, i))
        i = i + 1
    }
    akshar_rakh(dst, cnt, 0)
    nivartanam cnt
}

# khand_maap(s) — byte length of the string s (via vartani_aayam).

prakriya khand_maap(s) {
    nivartanam vartani_aayam(s)
}

# khand_anwesh(hay, hn, needle, nn) — byte index of first occurrence of
# needle in hay, or -1. Empty needle matches at 0.

prakriya khand_anwesh(hay, hn, needle, nn) {
    vitti h = hay
    vitti hlen = hn
    vitti nd = needle
    vitti nlen = nn
    vitti i = 0
    vitti match = 0
    vitti j = 0
    yadi (nlen < 0) { nivartanam 0 - 1 }
    yadi (nlen == 0) { nivartanam 0 }
    yadi (nlen > hlen) { nivartanam 0 - 1 }
    i = 0
    yavat (i <= hlen - nlen) {
        match = 1
        j = 0
        yavat (j < nlen) {
            yadi (akshar(h, i + j) != akshar(nd, j)) { match = 0 }
            j = j + 1
        }
        yadi (match == 1) { nivartanam i }
        i = i + 1
    }
    nivartanam 0 - 1
}

# khand_antah(hay, hn, needle, nn) — 1 if needle occurs in hay, else 0.

prakriya khand_antah(hay, hn, needle, nn) {
    yadi (khand_anwesh(hay, hn, needle, nn) >= 0) { nivartanam 1 }
    nivartanam 0
}

# khand_pratisthap(src, sn, find, fn, repl, out) — copy src to out, replacing
# every (non-overlapping) occurrence of find with repl. repl is
# 0-terminated (its length is derived, so a literal works) — repl
# cannot be a slice; khand_pratilip a slice into a terminated buffer first
# (see header, slice-boundary rules). Returns the
# new byte count. Empty find: copy verbatim. Caller allocates generously.

prakriya khand_pratisthap(src, sn, find, fn, repl, out) {
    vitti s = src
    vitti slen = sn
    vitti f = find
    vitti flen = fn
    vitti r = repl
    vitti dst = out
    vitti rlen = 0
    vitti wpos = 0
    vitti rpos = 0
    vitti match = 0
    vitti j = 0
    vitti k = 0
    yavat (akshar(r, rlen) != 0) { rlen = rlen + 1 }
    yadi (flen <= 0) {
        # flen < 0: same verbatim copy as empty find (the old
        # code looped forever on a negative find length).
        yavat (rpos < slen) {
            akshar_rakh(dst, wpos, akshar(s, rpos))
            wpos = wpos + 1
            rpos = rpos + 1
        }
        akshar_rakh(dst, wpos, 0)
        nivartanam wpos
    }
    yavat (rpos < slen) {
        match = 1
        yadi (rpos + flen > slen) {
            match = 0
        } anya {
            j = 0
            yavat (j < flen) {
                yadi (akshar(s, rpos + j) != akshar(f, j)) { match = 0 }
                j = j + 1
            }
        }
        yadi (match == 1) {
            k = 0
            yavat (k < rlen) {
                akshar_rakh(dst, wpos, akshar(r, k))
                wpos = wpos + 1
                k = k + 1
            }
            rpos = rpos + flen
        } anya {
            akshar_rakh(dst, wpos, akshar(s, rpos))
            wpos = wpos + 1
            rpos = rpos + 1
        }
    }
    akshar_rakh(dst, wpos, 0)
    nivartanam wpos
}

# khand_bhed(src, sn, sep, sepn, parts, maxparts) — split src on sep.
# Same length-prefixed segment format as varna_bhed (R9): parts holds
# [len0, b0, b1, ..., len1, b0, ...]; cells hold one byte value each.
# Returns the segment count (capped at maxparts). Empty separator: no
# split (one segment). Empty input: one empty segment.

prakriya khand_bhed(src, sn, sep, sepn, parts, maxparts) {
    vitti s = src
    vitti slen = sn
    vitti sp = sep
    vitti splen = sepn
    vitti dst = parts
    vitti maxp = maxparts
    vitti nseg = 0
    vitti wpos = 0
    vitti segstart = 0
    vitti rpos = 0
    vitti done = 0
    vitti fpos = 0
    vitti si = 0
    vitti sj = 0
    vitti smatch = 0
    vitti segend = 0
    vitti seglen = 0
    vitti sk = 0
    vitti ci = 0
    yadi (slen == 0) {
        dst[0] = 0
        nivartanam 1
    }
    yadi (splen <= 0) {
        # splen < 0: same one-segment result as empty separator
        # (the old code looped forever on a negative length).
        dst[0] = slen
        khand_mukt(s, slen, dst + 8)
        nivartanam 1
    }
    done = 0
    yavat (done == 0) {
        fpos = 0 - 1
        si = rpos
        yavat (si + splen <= slen) {
            smatch = 1
            sj = 0
            yavat (sj < splen) {
                yadi (akshar(s, si + sj) != akshar(sp, sj)) { smatch = 0 }
                sj = sj + 1
            }
            yadi (smatch == 1) {
                fpos = si
                si = slen
            } anya {
                si = si + 1
            }
        }
        segend = slen
        yadi (fpos >= 0) { segend = fpos }
        yadi (nseg < maxp) {
            seglen = segend - segstart
            dst[wpos] = seglen
            # unpack writes a 0 cell at dst[wpos+1+seglen]; the next
            # segment's length overwrites it (or it trails harmlessly).
            # Cell index -> byte offset: (wpos + 1) * 8.
            khand_mukt(s + segstart, seglen, dst + (wpos + 1) * 8)
            wpos = wpos + 1 + seglen
            nseg = nseg + 1
        }
        yadi (fpos < 0) {
            done = 1
        } anya {
            segstart = fpos + splen
            rpos = segstart
            yadi (rpos >= slen) {
                yadi (nseg < maxp) {
                    dst[wpos] = 0
                    nseg = nseg + 1
                }
                done = 1
            }
        }
    }
    nivartanam nseg
}

# khand_yuj(parts, count, sep, sepn, out) — inverse of khand_bhed for the
# length-prefixed format. Joins `count` segments with sep into a byte
# string. Returns the new byte count.

prakriya khand_chhid(src, sn, out) {
    vitti s = src
    vitti slen = sn
    vitti dst = out
    vitti lo = 0
    vitti go = 1
    vitti hi = 0
    vitti go2 = 1
    vitti wpos = 0
    vitti k = 0
    yavat (go == 1) {
        yadi (lo >= slen) {
            go = 0
        } anya {
            yadi (akshar(s, lo) == 32) { lo = lo + 1 } anya { go = 0 }
        }
    }
    hi = slen
    yavat (go2 == 1) {
        yadi (hi <= lo) {
            go2 = 0
        } anya {
            yadi (akshar(s, hi - 1) == 32) { hi = hi - 1 } anya { go2 = 0 }
        }
    }
    k = lo
    yavat (k < hi) {
        akshar_rakh(dst, wpos, akshar(s, k))
        wpos = wpos + 1
        k = k + 1
    }
    akshar_rakh(dst, wpos, 0)
    nivartanam wpos
}

# khand_unnat(src, sn, out) / khand_avanat — ASCII case conversion on byte
# strings. Returns the byte count. sn < 0: empty output (the old
# code wrote the terminator at out[-1], out of bounds).

prakriya khand_unnat(src, sn, out) {
    vitti s = src
    vitti slen = sn
    vitti dst = out
    vitti i = 0
    vitti c = 0
    yadi (slen < 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yavat (i < slen) {
        c = akshar(s, i)
        yadi (c >= 97) {
            yadi (c <= 122) { c = c - 32 }
        }
        akshar_rakh(dst, i, c)
        i = i + 1
    }
    akshar_rakh(dst, slen, 0)
    nivartanam slen
}

# khand_avanat(src, sn, out) — copies src (sn bytes) to out with A-Z lowercased to a-z, NUL-terminated; returns sn (0 for sn < 0).

prakriya khand_avanat(src, sn, out) {
    vitti s = src
    vitti slen = sn
    vitti dst = out
    vitti i = 0
    vitti c = 0
    yadi (slen < 0) {
        akshar_rakh(dst, 0, 0)
        nivartanam 0
    }
    yavat (i < slen) {
        c = akshar(s, i)
        yadi (c >= 65) {
            yadi (c <= 90) { c = c + 32 }
        }
        akshar_rakh(dst, i, c)
        i = i + 1
    }
    akshar_rakh(dst, slen, 0)
    nivartanam slen
}

# khand_aadi(src, sn, pre, pn) / khand_ant — 0/1 on byte strings.
# A negative prefix/suffix length is invalid: 0 (the old code
# treated it as empty and returned 1).

prakriya khand_aadi(src, sn, pre, pn) {
    vitti s = src
    vitti slen = sn
    vitti pr = pre
    vitti plen = pn
    vitti i = 0
    yadi (plen < 0) { nivartanam 0 }
    yadi (plen > slen) { nivartanam 0 }
    yavat (i < plen) {
        yadi (akshar(s, i) != akshar(pr, i)) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# khand_ant(src, sn, suf, sn2) — 1 if the src byte string (sn bytes) ends with suf (sn2 bytes), else 0.

prakriya khand_ant(src, sn, suf, sn2) {
    vitti s = src
    vitti slen = sn
    vitti sf = suf
    vitti sflen = sn2
    vitti i = 0
    yadi (sflen < 0) { nivartanam 0 }
    yadi (sflen > slen) { nivartanam 0 }
    yavat (i < sflen) {
        yadi (akshar(s, slen - sflen + i) != akshar(sf, i)) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# khand_tul(a, an, b, bn) — -1 / 0 / 1 (lexicographic by byte value).

prakriya khand_tul(a, an, b, bn) {
    vitti x = a
    vitti xn = an
    vitti y = b
    vitti yn = bn
    vitti i = 0
    vitti n = 0
    vitti cx = 0
    vitti cy = 0
    n = xn
    yadi (yn < n) { n = yn }
    yavat (i < n) {
        cx = akshar(x, i)
        cy = akshar(y, i)
        yadi (cx < cy) { nivartanam 0 - 1 }
        yadi (cx > cy) { nivartanam 1 }
        i = i + 1
    }
    yadi (xn < yn) { nivartanam 0 - 1 }
    yadi (xn > yn) { nivartanam 1 }
    nivartanam 0
}

# khand_viparyay(src, sn, out) — copy src reversed into out (WS3, R19).
# Two-pointer vinimay, so it is SAFE IN PLACE (src == out works). Writes
# a 0 terminator at out[sn]. Returns sn. sn <= 0 writes only the
# terminator, returns 0. Before this, reversing a byte string meant
# a hand-written loop at every call site.

prakriya khand_gan_swar(s, n) {
    vitti src = s
    vitti cnt = n
    vitti i = 0
    vitti c = 0
    vitti ch = 0
    yavat (i < cnt) {
        ch = akshar(src, i)
        yadi (ch == 97 || ch == 101 || ch == 105 || ch == 111 || ch == 117) {
            c = c + 1
        }
        i = i + 1
    }
    nivartanam c
}

# khand_gan_akshar(s, n, code) — count occurrences of byte `code` in
# the first n bytes (WS1, R20). Explicit-length form of gan_akshar;
# correct on slices. (For a substring, use khand_gan.)

prakriya khand_gan_akshar(s, n, code) {
    vitti src = s
    vitti cnt = n
    vitti cd = code
    vitti i = 0
    vitti c = 0
    yavat (i < cnt) {
        yadi (akshar(src, i) == cd) { c = c + 1 }
        i = i + 1
    }
    nivartanam c
}

# khand_anwesh_akshar(s, n, code) — first index of byte `code` in the first
# n bytes, or -1 (WS1, R20). Explicit-length form of anwesh_akshar.

prakriya khand_anwesh_akshar(s, n, code) {
    vitti src = s
    vitti cnt = n
    vitti cd = code
    vitti i = 0
    yavat (i < cnt) {
        yadi (akshar(src, i) == cd) { nivartanam i }
        i = i + 1
    }
    nivartanam 0 - 1
}

# khand_asti_sarv_ank(s, n) — 1 if all of the first n bytes are ASCII
# digits, else 0 (WS1, R20). Explicit-length form of asti_sarv_ank.
# Empty (n == 0) is 0, mirroring asti_sarv_ank.

prakriya khand_asti_sarv_ank(s, n) {
    vitti src = s
    vitti cnt = n
    vitti i = 0
    vitti ch = 0
    yadi (cnt <= 0) { nivartanam 0 }
    yavat (i < cnt) {
        ch = akshar(src, i)
        yadi (ch < 48 || ch > 57) { nivartanam 0 }
        i = i + 1
    }
    nivartanam 1
}

# khand_sam(a, an, b, bn) — 1 if the two byte strings are equal,
# else 0 (WS1, R20). Explicit-length form of varna_sam.

prakriya khand_sam(a, an, b, bn) {
    yadi (khand_tul(a, an, b, bn) == 0) { nivartanam 1 }
    nivartanam 0
}

prakriya madhava_vargmool(dasham v) {
    yadi (v <= 0.0) { nivartanam 0.0 }
    dasham g = v
    yadi (g < 1.0) { g = 1.0 }
    vitti i = 0
    yavat (i < 1000) {
        g = (g + v / g) / 2.0
        i = i + 1
    }
    nivartanam g
}

# Madhava's fast series for pi:  pi = sqrt(12) * sum (-1)^k / ((2k+1) * 3^k)

prakriya madhava_pi() {
    dasham root12 = madhava_vargmool(12.0)
    dasham sum = 0.0
    dasham p3 = 1.0
    vitti k = 0
    vitti util_chinha = 1
    yavat (k < 30) {
        dasham term = 1.0 / ((2.0 * k + 1.0) * p3)
        yadi (util_chinha > 0) {
            sum = sum + term
        } anya {
            sum = sum - term
        }
        p3 = p3 * 3.0
        util_chinha = 0 - util_chinha
        k = k + 1
    }
    nivartanam root12 * sum
}

# Madhava's sine series:  sin(x) = x - x^3/3! + x^5/5! - ...
# Evaluated on x reduced to [-PI, PI] (k = trunc(x / 2PI), one
# PI-adjustment). Without reduction the 16-term series was off
# by ~1e-4 at x = 10 and inf at x = 100. Exact for |x| <= ~1e15.

prakriya madhava_sin(dasham x) {
    dasham pi2 = 6.283185307179586
    dasham pi = 3.141592653589793
    vitti k = x / pi2
    dasham y = x - k * pi2
    yadi (y > pi) { y = y - pi2 }
    yadi (y < 0.0 - pi) { y = y + pi2 }
    dasham s = y
    dasham t = y
    vitti n = 1
    yavat (n < 16) {
        t = 0.0 - t * y * y / ((2.0 * n) * (2.0 * n + 1.0))
        s = s + t
        n = n + 1
    }
    nivartanam s
}

# Madhava's cosine series:  cos(x) = 1 - x^2/2! + x^4/4! - ...
# Same argument reduction as sin (was ~3.5e-4 off at x = 10).

prakriya madhava_atan(dasham x) {
    dasham ax = x
    vitti neg = 0
    yadi (ax < 0.0) {
        neg = 1
        ax = 0.0 - ax
    }
    yadi (ax > 1.0) {
        dasham r = madhava_pi() / 2.0 - madhava_atan(1.0 / ax)
        yadi (neg == 1) { nivartanam 0.0 - r }
        nivartanam r
    }
    dasham y = ax / (1.0 + madhava_vargmool(1.0 + ax * ax))
    dasham s = 0.0
    dasham yp = y
    vitti k = 0
    vitti util_chinha = 1
    yavat (k < 60) {
        dasham term = yp / (2.0 * k + 1.0)
        yadi (util_chinha > 0) {
            s = s + term
        } anya {
            s = s - term
        }
        yp = yp * y * y
        util_chinha = 0 - util_chinha
        k = k + 1
    }
    dasham res = 2.0 * s
    yadi (neg == 1) { nivartanam 0.0 - res }
    nivartanam res
}

prakriya mala_nava(n) {
    vitti c = n
    vitti sz = 0
    # A count so large the byte size overflows returns 0 (R35: before multiplying).
    yadi (c < 0) { nivartanam 0 }   # R37: -2^61 + 1 wrapped to 8
    yadi (c > 1152921504606846975) { nivartanam 0 }
    sz = c * 8
    yadi (sz < 0) { nivartanam 0 }
    nivartanam nirmmita(sz)
}

# mala_sangrah(arr, i, val) — stores val at arr[i] (qword cells, no bounds check); returns 0.

prakriya mala_grah(arr, i) {
    vitti a = arr
    vitti j = i
    nivartanam pad8(a + j * 8)
}

# mala_purn(arr, val, n) — fills arr[0..n-1] with val; returns 0.

prakriya mala_purn(arr, val, n) {
    vitti a = arr
    vitti v = val
    vitti c = n
    vitti j = 0
    yavat (j < c) {
        likh8(a + j * 8, v)
        j = j + 1
    }
    nivartanam 0
}

# mala_pratilip(dst, src, n) — copies n qwords from src to dst; returns 0.

prakriya mala_pratilip(dst, src, n) {
    vitti d = dst
    vitti s = src
    vitti c = n
    vitti j = 0
    yavat (j < c) {
        likh8(d + j * 8, pad8(s + j * 8))
        j = j + 1
    }
    nivartanam 0
}

# mala_yog(arr, n) — sum of arr[0..n-1].

prakriya mala_yog(arr, n) {
    vitti a = arr
    vitti c = n
    vitti s = 0
    vitti j = 0
    yavat (j < c) {
        s = s + pad8(a + j * 8)
        j = j + 1
    }
    nivartanam s
}

# mala_sangrah_surakshit(arr, i, val, n) — bounds-checked store: 1 and stores if 0 <= i < n, else 0 and stores nothing.

prakriya mala_sangrah_surakshit(arr, i, val, n) {
    vitti a = arr
    vitti j = i
    vitti v = val
    vitti c = n
    yadi (j < 0) { nivartanam 0 }
    yadi (j >= c) { nivartanam 0 }
    likh8(a + j * 8, v)
    nivartanam 1
}

# mala_grah_surakshit(arr, i, n) — bounds-checked load: arr[i] if 0 <= i < n, else 0.

prakriya mala_grah_surakshit(arr, i, n) {
    vitti a = arr
    vitti j = i
    vitti c = n
    yadi (j < 0) { nivartanam 0 }
    yadi (j >= c) { nivartanam 0 }
    nivartanam pad8(a + j * 8)
}
